 19	// Brain. Loading the full guard, not just the tombstone file, keeps capture
 20	// failing on the same invalid durable-transaction state every read would.
 21	func CaptureRetrievalPrivacyPolicy(brainDir string) (RetrievalPrivacyPolicy, error) {
 22		guard, err := LoadSessionReadGuard(brainDir, nil)
 23		if err != nil {
 24			return RetrievalPrivacyPolicy{}, err
 25		}
 26		return RetrievalPrivacyPolicy{BrainDir: brainDir, Identity: guard.PolicyIdentity}, nil
 27	}
